<template><section class="ledger" v-loading="loading"><div class="heading"><strong>整单重量总账</strong><el-select v-model="item" placeholder="全部产品" clearable @change="load"><el-option v-for="row in data?.items??[]" :key="row.itemId" :value="row.itemId" :label="product(row)"/></el-select><el-button :disabled="loading" @click="load">刷新总账</el-button><el-button v-if="canExport" :disabled="loading||!data" :loading="exporting" @click="download">导出</el-button></div><el-alert v-if="failed" title="总账加载失败，请刷新重试" type="error" :closable="false"/><template v-if="data"><p>{{data.workOrderNo}} · {{statusNames[data.status]}} · {{displayDateTime(data.readTime)}}</p><p>新增投入＝原料领入＋外部半成品领入＋来源半成品净调整。内部流转不重复累计；释放不改变重量。未结算差额含待确认损耗，不代表已称量在制实物。</p><el-alert v-for="warning in data.anomalies" :key="warning" :title="warning" type="warning" :closable="false"/><div class="scroll"><el-table :data="rows" border row-key="key" @expand-change="expanded"><el-table-column type="expand"><template #default="{row}"><div v-loading="detailLoading[row.key]" class="lines"><p v-if="detailErrors[row.key]" role="alert">明细加载失败或总账已变化，请刷新总账。</p><el-table :data="details[row.key]?.rows??[]" border><el-table-column prop="orderNo" label="单据／批次" min-width="210"/><el-table-column prop="code" label="物料编号" min-width="140"/><el-table-column prop="name" label="名称" min-width="140"/><el-table-column prop="weight" label="净重(g)" min-width="140"/><el-table-column prop="quantity" label="件数" width="90"/></el-table><el-pagination v-if="details[row.key]?.total>20" :total="details[row.key].total" :page-size="20" :current-page="pages[row.key]||1" layout="prev,pager,next" @current-change="page=>loadLines(row.key,page)"/></div></template></el-table-column><el-table-column prop="label" label="重量项目" min-width="230"/><el-table-column prop="value" label="净重(g)" min-width="160"/></el-table></div></template></section></template>
<script setup lang="ts">
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission = useActionPermission()
import {ref,computed,watch,onBeforeUnmount} from 'vue';import request from '@/utils/request';import {saveAs} from 'file-saver';import {ElMessage} from 'element-plus';import useUserStore from '@/store/modules/user';import {displayDateTime} from '@/utils/display-date-time'
type R=Record<string,any>;const props=defineProps<{workOrderId:string}>(),user=useUserStore(),canExport=computed(()=>actionPermission.has('metal:work-order:weight-export')),data=ref<R>(),item=ref(''),loading=ref(false),failed=ref(false),exporting=ref(false),details=ref<R>({}),detailLoading=ref<R>({}),detailErrors=ref<R>({}),pages=ref<R>({});let epoch=0,disposed=false
const names:Record<string,string>={RAW_ISSUED:'原料领入',EXTERNAL_SEMI_ISSUED:'外部半成品领入',SEMI_ADJUSTMENT:'来源半成品库存净调整',INPUT:'新增投入合计',FINISHED_OUTPUT:'成品累计产出',OWN_SEMI_STOCK:'本单半成品在库',CROSS_SEMI_OUT:'半成品跨单净转出',OTHER_SEMI_OUT:'其他半成品净出库',SETTLED_LOSS:'已结算损耗',PROCESS_RAW_RETURN_GROSS:'加工余料累计回收',INTERNAL_RECOVERED_RAW:'回收原料本单净再领用（仅追溯）',PROCESS_RAW_RETURN:'加工余料净还库',RAW_RETURN:'原料还库',EXTERNAL_SEMI_RETURN:'外部半成品还库',OPEN_DIFFERENCE:'未结算在制差额（待确认损耗）',RECONCILIATION_DIFFERENCE:'核对差额（正常应为0）',INTERNAL_SEMI:'内部半成品流转（仅追溯）'},statusNames:Record<string,string>={BALANCED:'已平衡',REVIEW:'待核对',INCOMPLETE:'依据不完整，不能确认平衡'}
const rows=computed(()=>Object.entries(names).map(([key,label])=>({key,label,value:data.value?.totals[key]??'—'})))
function product(row:R){try{return JSON.parse(row.productSnapshot).name||'产品'}catch{return '产品'}}
async function load(){const ticket=++epoch,work=props.workOrderId,selected=item.value,current=()=>!disposed&&ticket===epoch&&work===props.workOrderId&&selected===item.value;loading.value=true;failed.value=false;data.value=undefined;details.value={};detailLoading.value={};detailErrors.value={};pages.value={};try{const r:any=await request({url:`/metal/work-order/${work}/weight-balance`,params:{itemId:selected||undefined},isContextCurrent:current});if(current())data.value=r.data}catch{if(current())failed.value=true}finally{if(current())loading.value=false}}
async function loadLines(category:string,page=1){const ticket=epoch,work=props.workOrderId,token=data.value?.snapshotToken,current=()=>!disposed&&ticket===epoch&&work===props.workOrderId&&token===data.value?.snapshotToken&&pages.value[category]===page;pages.value[category]=page;detailLoading.value[category]=true;detailErrors.value[category]=false;try{const r:any=await request({url:`/metal/work-order/${work}/weight-balance/lines`,params:{itemId:item.value||undefined,category,page,size:20,snapshotToken:token},isContextCurrent:current});if(current())details.value[category]=r.data}catch{if(current()){details.value[category]=undefined;detailErrors.value[category]=true}}finally{if(current())detailLoading.value[category]=false}}
function expanded(row:R,expandedRows:R[]){if(expandedRows.some(r=>r.key===row.key)&&!details.value[row.key])void loadLines(row.key)}
async function download(){if(!data.value||loading.value||exporting.value)return;const ticket=epoch,work=props.workOrderId,token=data.value.snapshotToken,current=()=>!disposed&&ticket===epoch&&work===props.workOrderId&&token===data.value?.snapshotToken;exporting.value=true;try{const blob:any=await request({url:`/metal/work-order/${work}/weight-balance/export`,params:{itemId:item.value||undefined,snapshotToken:token},responseType:'blob',isContextCurrent:current});if(current()){if(blob.type?.includes('json')){ElMessage.error('总账已变化或无导出权限，请刷新后重试');return}saveAs(blob,'整单重量总账.xlsx')}}catch{if(current())ElMessage.error('导出失败，请刷新后重试')}finally{exporting.value=false}}
watch(()=>props.workOrderId,()=>{item.value='';void load()},{immediate:true});onBeforeUnmount(()=>{disposed=true;epoch++})
</script>
<style scoped>.ledger{min-width:0;margin-top:16px;padding:16px;border:1px solid #e4e7ed;border-radius:10px;background:#fff}.heading{display:flex;align-items:center;flex-wrap:wrap;gap:12px}.heading .el-select{width:220px}p{font-size:13px;color:#667085;line-height:1.7}.scroll{max-width:100%;overflow-x:auto}.lines{padding:12px}.el-alert{margin-bottom:10px}@media(max-width:480px){.ledger{padding:10px}.heading .el-select{width:100%}}</style>
